  min-width: 56px;
  color: var(--muted-foreground, #71717a);
  font-size: 12px;
}

.inspection-result__detail-value {
  margin: 0;
  min-width: 0;
  flex: 1 1 140px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  color: var(--foreground, #18181b);
  word-break: break-word;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.inspection-result__detail-empty {
  margin: 0;
  font-size: 12px;
  color: var(--muted-foreground, #71717a);
}

.inspection-result__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}

.inspection-result__copy {
  flex: none;
  padding: 3px 10px;
  border: 1px solid var(--border, #e4e4e7);
  border-radius: 6px;
  background: var(--background, #ffffff);
  color: var(--foreground, #18181b);
  font-size: 12px;
  line-height: 1.6;
  cursor: pointer;
}

.inspection-result__copy:hover {
  background: var(--muted, #f4f4f5);
}

.inspection-result__copy:focus-visible {
  outline: 2px solid var(--ring, #2563eb);
  outline-offset: 1px;
}

.inspection-result__ok {
  margin: 0;
  font-size: 12px;
  color: var(--muted-foreground, #71717a);
}

.inspection-result__empty {
  margin: 0;
  font-size: 12px;
  color: var(--muted-foreground, #71717a);
}

.inspection-result__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
